from calc1_core import *
import mpmath as mp
mp.mp.dps=60
D=CalcDoc('1.5',[60,61,62],lambda n:60 if n<=8 else 61 if n<=32 else 62)
def add(n,st,steps,ans,check,parts=()):return D.add(n,('극한·한쪽 극한·무한극한','Limits,one-sided limits,and infinite limits'),st,('점의 실제 함수값과 주변에서 접근하는 값을 구분한다.','Distinguish the value at a point from values approached nearby.'),steps,ans,check,parts)
def vals(fn,items,digits=6):
 pairs=[(str(z),mp.mpf(fn(mp.mpf(str(z)))))for z in items]
 return '; '.join(z+' → '+f'{float(v):.{digits}f}'for z,v in pairs)
add(1,('lim(x→2)f(x)=5의 의미를 설명하라. 동시에 f(2)=3일 수 있는가?','Explain lim(x→2)f(x)=5.Can f(2)=3 nevertheless?'),[('2와 다른 입력을2에 충분히 가까이 고르면 함수값을 원하는 만큼5 가까이 만들 수 있다는 뜻이다.','Inputs distinct from2 can be chosen sufficiently close to2 so that their outputs are as close to5 as desired.'),('극한은 x=2 자체의 값을 사용하지 않는다.','The limit does not use the value at x=2 itself.')],('가능하다. 예:f(x)=5(x≠2),f(2)=3.','Yes.For example f(x)=5 for x≠2 and f(2)=3.'),('이 예에서 모든 뚫린 근방의 함수값은 정확히5이지만 지정점의 값은3이다.','Every punctured neighborhood has output exactly5,while the assigned value at the point is3.'))
add(2,('x→1⁻에서 f→3,x→1⁺에서 f→7이라는 말의 의미와 양쪽 극한 존재 여부를 설명하라.','Explain what f→3 as x→1⁻ and f→7 as x→1⁺ mean,and whether the two-sided limit exists.'),[('1보다 작은 입력으로 접근하면3,큰 입력으로 접근하면7에 가까워진다.','Approaching with inputs below1 gives outputs near3;approaching from above gives outputs near7.'),('양쪽 극한이 존재하려면 두 한쪽 극한이 같은 값이어야 한다.','A two-sided limit requires the one-sided limits to agree.')],('3≠7이므로 lim(x→1)f(x)는 존재하지 않는다.','Since3≠7,the two-sided limit does not exist.'),('서로 다른 두 접근 수열이 다른 출력 극한을 주므로 하나의 공통값을 정할 수 없다.','Two sequences approaching from opposite sides yield different output limits,excluding a common value.'))
add(3,('(a)lim(x→−3)f(x)=∞,(b)lim(x→4⁺)f(x)=−∞의 의미를 설명하라.','Explain(a)lim(x→−3)f(x)=∞ and(b)lim(x→4⁺)f(x)=−∞.'),[('(a)−3의 양쪽에서 충분히 가까운 입력을 택하면 함수값이 임의의 큰 양수보다 커진다.','(a)For inputs sufficiently close to−3 from either side,outputs exceed any prescribed positive bound.'),('(b)4보다 큰 입력을4에 충분히 가깝게 택하면 함수값이 임의의 큰 음수보다 작아진다.','(b)For inputs sufficiently close to4 from above,outputs fall below any prescribed negative bound.')],('무한대는 실제 실수 함수값이 아니라 제한 없이 증가하거나 감소하는 행동을 뜻한다.','Infinity describes unbounded increase or decrease,not an ordinary real function value.'),('두 경우 모두 해당 접근 방향에서 수직점근선이 생기지만 f(−3),f(4)의 정의 여부는 별개이다.','Both imply vertical-asymptotic behavior in the indicated directions,but do not determine whether f(−3) or f(4) is defined.'),list('ab'))
add(4,('그래프의 x=2에서 왼쪽 가지는 닫힌(2,3),오른쪽 가지는 열린(2,1)이고 x=4에서는 열린(4,4)로 양쪽이 이어진다.(a)2왼쪽,(b)2오른쪽,(c)2양쪽 극한,(d)f(2),(e)4양쪽 극한,(f)f(4)를 구하라.','At x=2 the graph has filled(2,3) on the left branch and open(2,1) on the right.At x=4 both sides approach open(4,4).Find(a)left limit at2,(b)right limit at2,(c)two-sided limit at2,(d)f(2),(e)limit at4,(f)f(4).'),[('2에서는 두 접근 높이3과1이 다르다.4에서는 양쪽 높이는4이지만 그 점은 제외된다.','At2,the approaching heights3 and1 differ.At4,both sides approach4,but the point itself is excluded.')],('(a)3,(b)1,(c)없음,(d)3,(e)4,(f)정의되지 않음.','(a)3,(b)1,(c)does not exist,(d)3,(e)4,(f)undefined.'),('닫힌 점은 함수값에만 적용하고 열린 점의 높이는 극한 판독에 사용했다.','Filled points determine function values;open-point heights can still determine limits.'),list('abcdef'))
D.fig(4,[panel('Jump at2;hole at4',(-2,6,0,5),[[(-2,1.7),(-1,2.6),(0,3.2),(1,3.3),(2,3)],[(2,1),(3,2),(4,4),(4.5,4),(5,3.5),(6,1.8)]],[(2,3),(2,1,'open'),(4,4,'open')],xticks=[0,2,4,6])])
add(5,('그래프는 x=1에서 높이2로 이어진다.x=3에서 왼쪽 열린점(3,1),오른쪽 열린점(3,4),별도 닫힌점(3,3)이 있다.(a)1의 극한,(b)3왼쪽,(c)3오른쪽,(d)3양쪽 극한,(e)f(3)를 구하라.','The graph passes continuously through height2 at x=1.At x=3 it has left open point(3,1),right open point(3,4),and isolated filled point(3,3).Find(a)limit at1,(b)left limit at3,(c)right limit at3,(d)two-sided limit at3,(e)f(3).'),[('x=3에서는 왼쪽이1,오른쪽이4로 접근하며 값3은 접근값을 바꾸지 않는다.','At3,the left approach is1 and right approach is4;the assigned value3 does not change these limits.')],('(a)2,(b)1,(c)4,(d)없음,(e)3.','(a)2,(b)1,(c)4,(d)does not exist,(e)3.'),('양쪽 극한이 같지 않아 f(3)의 값을 어떻게 바꾸어도 그 극한은 생기지 않는다.','Because the one-sided limits disagree,no choice of f(3) creates a two-sided limit.'),list('abcde'))
D.fig(5,[panel('One-sided limits and assigned value',(-2,6,0,5),[[(-2,3.8),(-1,3.5),(0,3),(1,2),(2,.9),(2.5,.8),(3,1)],[(3,4),(4,3.7),(5,2.8),(6,1)]],[(3,1,'open'),(3,4,'open'),(3,3)],xticks=[0,1,2,3,4,5,6])])
add(6,('h의 그래프에서 x=−3에는 열린 높이4, x=0에는 왼쪽 닫힌 높이1과 오른쪽 열린 높이−1, x=2에는 열린 높이2가 있다.5의 왼쪽에서는 높이2~4로 계속 진동하고 오른쪽은 높이3에서 시작한다.(a,b,c)−3의 왼쪽·오른쪽·양쪽 극한,(d)h(−3),(e,f,g)0의 세 극한,(h)h(0),(i)2의 극한,(j)h(2),(k)5오른쪽,(l)5왼쪽 극한을 구하라.','The graph h has an open point at height4 for x=−3;at0,it has left filled height1 and right open height−1;at2,it has open height2.To the left of5 it oscillates between2 and4,while the right branch starts at height3.Find(a,b,c)left,right,two-sided limits at−3,(d)h(−3),(e,f,g)the three limits at0,(h)h(0),(i)limit at2,(j)h(2),(k)right and(l)left limit at5.'),[('−3과2의 구멍에서는 양쪽 접근값이 같아 극한이 있다.0에서는 한쪽 높이가 달라 양쪽 극한이 없다.','The holes at−3 and2 have matching one-sided limits.At0 the unequal approaching heights prevent a two-sided limit.'),('5왼쪽의 진동 폭은 줄어들지 않으므로 하나의 수에 가까워지지 않는다.','The oscillation amplitude on the left of5 does not shrink,so it does not approach one number.')],('(a)4,(b)4,(c)4,(d)정의되지 않음,(e)1,(f)−1,(g)없음,(h)1,(i)2,(j)정의되지 않음,(k)3,(l)없음.','(a)4,(b)4,(c)4,(d)undefined,(e)1,(f)−1,(g)does not exist,(h)1,(i)2,(j)undefined,(k)3,(l)does not exist.'),('h(0)은 닫힌 점1이다.5왼쪽은 유한 범위 안에서 진동하므로∞나−∞로도 발산하지 않는다.','h(0) is the filled value1.The bounded left oscillation at5 tends to neither∞ nor−∞.'),list('abcdefghijkl'))
D.fig(6,[panel('Holes,jump,and nonshrinking oscillation',(-5,9,-2,6),[[(-5,0),(-4,2.7),(-3,4),(-2,2),(-1,1.3),(0,1)],[(0,-1),(1,0),(2,2),(2.8,4)],samples(lambda z:3+math.sin(5/(5-z)),2.8,4.97,1500),[(5,3),(6,4.5),(7,4.8),(8,4.3),(9,3)]], [(-3,4,'open'),(0,1),(0,-1,'open'),(2,2,'open')],xticks=[-4,-3,-2,0,2,4,5,6,8],yticks=[-1,0,1,2,3,4,5])],('특이점과 진동 범위를 보존한 개략도.','Schematic preserving the special points and oscillation range.'))
add(7,('g의 그래프는 x=2에서 두 다른 열린 높이로 갈라지고 값은 없으며,x=4에서 서로 다른 한쪽 높이를 갖고 오른쪽 가지 시작은 닫힌 점이다.x=5에는 양쪽으로 이어지는 열린 구멍이 있다.(a)극한은 없고 g(a)는 있음,(b)극한은 있고 g(a)는 없음,(c)두 유한 한쪽 극한은 있지만 양쪽 극한은 없음,(d)오른쪽 극한=g(a),왼쪽 극한≠g(a)인 a를 각각 구하라.','At x=2,g has two different open approaching heights and no value.At4,it has different one-sided limits and a filled right-branch starting point.At5,it has a hole on an otherwise continuous branch.Find a for(a)no limit but defined g(a),(b)a limit but undefined g(a),(c)two finite one-sided limits but no two-sided limit,(d)right limit=g(a) but left limit≠g(a).'),[('각 후보2,4,5에서 극한의 일치 여부와 실제 닫힌 점 여부를 따로 확인한다.','For2,4,5,separately check agreement of the limits and presence of a filled point.')],('(a)4,(b)5,(c)2 또는4,(d)4.','(a)4,(b)5,(c)2 or4,(d)4.'),('2에서는 값 자체가 없어(a),(d)에 쓸 수 없고5에서는 한쪽 극한이 같아(c)에 쓸 수 없다.','At2 there is no function value,excluding(a),(d);at5 the one-sided limits agree,excluding(c).'),list('abcd'))
D.fig(7,[panel('Candidate inputs2,4,5',(-1,7,-2,4),[[(-1,-1),(0,-.5),(1,1.5),(2,2.8)],[(2,1.8),(3,1),(4,.5)],[(4,2.3),(5,1.7),(6,.6),(7,-1.2)]],[(2,2.8,'open'),(2,1.8,'open'),(4,.5,'open'),(4,2.3),(5,1.7,'open')],xticks=[0,2,4,5,6])])
add(8,('A의 그래프는 x=−3에서 양쪽 위로 발산,x=−1에서 양쪽 아래로 발산,x=2에서 왼쪽 아래·오른쪽 위로 발산한다.(a)−3의 극한,(b)2왼쪽,(c)2오른쪽,(d)−1의 극한,(e)수직점근선을 구하라.','The graph A diverges upward on both sides of−3,downward on both sides of−1,and downward on the left/upward on the right of2.Find(a)limit at−3,(b)left at2,(c)right at2,(d)limit at−1,(e)vertical asymptotes.'),[('위로 제한 없이 올라가면+∞,아래로 내려가면−∞로 표시한다.','Unbounded upward behavior is+∞;unbounded downward behavior is−∞.')],('(a)+∞,(b)−∞,(c)+∞,(d)−∞,(e)x=−3,−1,2.','(a)+∞,(b)−∞,(c)+∞,(d)−∞,(e)x=−3,−1,2.'),('수직점근선은 적어도 한쪽의 무한극한으로 확인하며 x축 교점은 점근선과 관계없다.','A vertical asymptote requires an infinite limit from at least one side;ordinary x-intercepts are irrelevant.'),list('abcde'))
add(9,('f의 그래프는 x=−7에서 양쪽 아래로,x=−3과0에서 양쪽 위로,x=6에서 왼쪽 아래·오른쪽 위로 발산한다.(a)−7,(b)−3,(c)0의 극한,(d)6왼쪽,(e)6오른쪽 극한,(f)수직점근선을 구하라.','The graph f diverges down on both sides of−7,up on both sides of−3 and0,and down on the left/up on the right of6.Find(a)limit at−7,(b)at−3,(c)at0,(d)left at6,(e)right at6,(f)vertical asymptotes.'),[('각 수직선의 양쪽에서 곡선이 향하는 위·아래 방향을 따로 읽는다.','Read the upward or downward direction separately on each side of every vertical line.')],('(a)−∞,(b)+∞,(c)+∞,(d)−∞,(e)+∞,(f)x=−7,−3,0,6.','(a)−∞,(b)+∞,(c)+∞,(d)−∞,(e)+∞,(f)x=−7,−3,0,6.'),('6에서는 서로 다른 부호의 발산으로 양쪽 무한극한은 하나로 정할 수 없지만 수직점근선은 존재한다.','At6 the opposite divergence signs prevent a common two-sided infinite limit,but there is still a vertical asymptote.'),list('abcdef'))
add(10,('교재의 약물 그래프에서4시간마다150 mg을 추가하며,t=12 직전 곡선은150 mg,직후 곡선은300 mg에서 시작한다.12의 왼쪽·오른쪽 극한과 의미를 구하라.','In the textbook drug-level graph,150 mg is added every4 hours.The curve approaches150 mg just before t=12 and starts at300 mg just afterward.Find and interpret the one-sided limits at12.'),[('왼쪽 극한은 새 주입 직전 남은 양,오른쪽 극한은 주입 직후의 양이다.','The left limit is the amount remaining before the injection;the right limit is the amount immediately afterward.')],d(r'\lim_{t\to12^-}f(t)=150\ \mathrm{mg},\quad\lim_{t\to12^+}f(t)=300\ \mathrm{mg}'),('두 접근값의 차300−150=150 mg이 주어진 추가량과 일치한다.','The jump300−150=150 mg agrees with the stated added amount.'))
D.fig(10,[panel('Drug amount near the12-hour jump',(8,16,0,330),[[(8,262),(9,226),(10,194),(11,170),(12,150)],[(12,300),(13,262),(14,230),(15,205),(16,187)]],[(12,150),(12,300,'open')],xticks=[8,10,12,14,16],yticks=[0,150,300],xlabel='hours',ylabel='mg')],('12시간의 한쪽 극한을 강조한 교재 자료 개략도.','Schematic of the textbook data emphasizing the one-sided limits at12 hours.'))
for n,expr,ko,en,excluded,curves,dots,bounds in [(11,r'\begin{cases}\cos x&x\le0\\1-x&0<x<1\\1/x&x\ge1\end{cases}','0では左右とも1で一致する。1では左0、右1で不一致である。','At0 both sides approach1.At1 the left limit0 differs from the right limit1.',1,[samples(math.cos,-4,0),[(0,1),(1,0)],samples(lambda z:1/z,1,4)],[(0,1),(1,0,'open'),(1,1)],(-4,4,-1.5,2)),(12,r'\begin{cases}\sqrt[3]x&x\le-1\\x&-1<x\le2\\(x-1)^2&x>2\end{cases}','−1では左右とも−1で一致する。2では左2、右1で不一致である。','At−1 both sides approach−1.At2 the left limit2 differs from the right limit1.',2,[samples(lambda z:math.copysign(abs(z)**(1/3),z),-4,-1),[(-1,-1),(2,2)],samples(lambda z:(z-1)**2,2,4)],[(-1,-1),(2,2),(2,1,'open')],(-4,4,-3,10))]:
 add(n,('함수 '+m('f(x)='+expr)+'를 그리고 lim(x→a)f(x)가 존재하는 a를 구하라.','Sketch '+m('f(x)='+expr)+' and determine all a for which lim(x→a)f(x) exists.'),[('각 조각 내부에서는 연속이므로 접합점의 한쪽 극한만 추가로 검사한다.','Each piece is continuous on its interior,so only junctions require additional one-sided checks.'),(ko,en)],d(r'a\in\mathbb R\setminus\{'+str(excluded)+r'\}'),('각 접합점에서 실제 지정값과 무관하게 두 조각의 접근값을 계산했다.','At each junction the limits of both formulas were evaluated independently of the assigned point value.'))
 D.fig(n,[panel('Piecewise limits',bounds,curves,dots)])
add(13,('f(x)=x√(1+x⁻²)의 그래프에서(a)0왼쪽,(b)0오른쪽,(c)양쪽 극한을 구하라.','Use the graph of f(x)=x√(1+x⁻²) to determine(a)the left limit at0,(b)the right limit,and(c)the two-sided limit.'),[(d(r'x\sqrt{1+x^{-2}}=\frac{x}{|x|}\sqrt{x^2+1}=\begin{cases}-\sqrt{x^2+1}&x<0\\\sqrt{x^2+1}&x>0\end{cases}'),d(r'x\sqrt{1+x^{-2}}=\frac{x}{|x|}\sqrt{x^2+1}=\begin{cases}-\sqrt{x^2+1}&x<0\\\sqrt{x^2+1}&x>0\end{cases}'))],('(a)−1,(b)1,(c)없음.','(a)−1,(b)1,(c)does not exist.'),('√(x²)=|x|이므로 x로 잘못 약분하면 왼쪽 부호를 잃는다.','Since√(x²)=|x|,canceling it as x would incorrectly lose the left-hand sign.'),list('abc'))
D.fig(13,[panel('Opposite limiting heights',(-3,3,-4,4),[samples(lambda z:-math.sqrt(z*z+1),-3,0),samples(lambda z:math.sqrt(z*z+1),0,3)],[(0,-1,'open'),(0,1,'open')])])
add(14,('f(x)=(3^(1/x)−2)/(3^(1/x)+1)의 그래프에서(a)0왼쪽,(b)0오른쪽,(c)양쪽 극한을 구하라.','For f(x)=(3^(1/x)−2)/(3^(1/x)+1),use its graph to find(a)left limit at0,(b)right limit,(c)two-sided limit.'),[('왼쪽에서는1/x→−∞라3^(1/x)→0,오른쪽에서는3^(1/x)→∞이다.','On the left,1/x→−∞ and3^(1/x)→0;on the right,3^(1/x)→∞.'),('u=3^(1/x)로 쓰면 f=(u−2)/(u+1)=1−3/(u+1)이다.','With u=3^(1/x),write f=(u−2)/(u+1)=1−3/(u+1).')],('(a)−2,(b)1,(c)없음.','(a)−2,(b)1,(c)does not exist.'),('분모 u+1은 양수라 다른 특이점은 없고, 두 유한 접근값이 다르다.','The denominator u+1 is positive,and the two finite approaching values differ.'),list('abc'))
def stable14(z):
 if z>0:return 1-3*math.exp(-math.log(3)/z)/(1+math.exp(-math.log(3)/z))
